{
  "name": "ScienceGrade Pro",
  "description": "A weighted MCQ grading tool for science teachers to calculate scores based on variable answer weights and generate printable student reports."
}

export type Option = 'A' | 'B' | 'C' | 'D' | 'E';

export const OPTIONS: Option[] = ['A', 'B', 'C', 'D', 'E'];
export const QUESTION_COUNT = 10;

export interface TestMetadata {
  testName: string;
  teacherName: string;
  grade: string;
  schoolName: string;
  section: string;
}

// The scoring key defines how many points each option is worth for each question
export interface ScoringKey {
  [questionIndex: number]: {
    [key in Option]: number;
  };
}

export interface StudentResult {
  id: string;
  name: string;
  answers: {
    [questionIndex: number]: Option;
  };
  totalScore: number;
  questionScores: {
    [questionIndex: number]: number;
  };
}

import React, { useEffect } from 'react';
import { TestMetadata, ScoringKey, OPTIONS, QUESTION_COUNT, Option } from '../types';
import { ClipboardList, ArrowRight, Wand2 } from 'lucide-react';

interface TestSetupProps {
  metadata: TestMetadata;
  scoringKey: ScoringKey;
  onMetadataChange: (meta: TestMetadata) => void;
  onScoringKeyChange: (key: ScoringKey) => void;
  onNext: () => void;
}

export const TestSetup: React.FC<TestSetupProps> = ({
  metadata,
  scoringKey,
  onMetadataChange,
  onScoringKeyChange,
  onNext,
}) => {
  // Initialize scoring key if empty
  useEffect(() => {
    if (Object.keys(scoringKey).length === 0) {
      const initialKey: ScoringKey = {};
      for (let i = 1; i <= QUESTION_COUNT; i++) {
        initialKey[i] = { A: 0, B: 0, C: 0, D: 0, E: 0 };
      }
      onScoringKeyChange(initialKey);
    }
  }, []);

  const handleMetaChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onMetadataChange({ ...metadata, [e.target.name]: e.target.value });
  };

  const handleScoreChange = (qIndex: number, option: Option, value: string) => {
    const numVal = parseInt(value) || 0;
    onScoringKeyChange({
      ...scoringKey,
      [qIndex]: {
        ...scoringKey[qIndex],
        [option]: numVal,
      },
    });
  };

  const applyDefaultPattern = () => {
    // Pattern: A=4, B=3, C=2, D=1, E=0
    const newKey: ScoringKey = {};
    for (let i = 1; i <= QUESTION_COUNT; i++) {
      newKey[i] = { A: 4, B: 3, C: 2, D: 1, E: 0 };
    }
    onScoringKeyChange(newKey);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <div className="flex items-center gap-2 mb-4 text-slate-800">
          <ClipboardList className="w-5 h-5 text-blue-600" />
          <h2 className="text-xl font-bold">1. Test Details</h2>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-600 mb-1">Test Name</label>
            <input
              name="testName"
              value={metadata.testName}
              onChange={handleMetaChange}
              className="w-full border border-slate-300 rounded-lg p-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              placeholder="e.g. Science Midterm 1"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-600 mb-1">Teacher Name</label>
            <input
              name="teacherName"
              value={metadata.teacherName}
              onChange={handleMetaChange}
              className="w-full border border-slate-300 rounded-lg p-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              placeholder="e.g. Mr. Smith"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-600 mb-1">School Name</label>
            <input
              name="schoolName"
              value={metadata.schoolName}
              onChange={handleMetaChange}
              className="w-full border border-slate-300 rounded-lg p-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              placeholder="e.g. Lincoln High"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-600 mb-1">Grade / Class</label>
            <input
              name="grade"
              value={metadata.grade}
              onChange={handleMetaChange}
              className="w-full border border-slate-300 rounded-lg p-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              placeholder="e.g. 10th Grade"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-600 mb-1">Section</label>
            <input
              name="section"
              value={metadata.section}
              onChange={handleMetaChange}
              className="w-full border border-slate-300 rounded-lg p-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              placeholder="e.g. Boys Section A"
            />
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2 text-slate-800">
            <ClipboardList className="w-5 h-5 text-blue-600" />
            <h2 className="text-xl font-bold">2. Scoring Model (Model Answer)</h2>
          </div>
          <button
            onClick={applyDefaultPattern}
            className="flex items-center gap-2 text-sm text-blue-600 hover:text-blue-800 bg-blue-50 px-3 py-1.5 rounded-lg transition-colors"
          >
            <Wand2 className="w-4 h-4" />
            Auto-fill (A=4, B=3...)
          </button>
        </div>

        <p className="text-slate-500 text-sm mb-4">
          Enter the marks awarded for each choice (A-E) for each question.
        </p>

        <div className="overflow-x-auto">
          <table className="w-full text-sm text-center border-collapse">
            <thead>
              <tr className="bg-slate-50 text-slate-700">
                <th className="p-3 border-b border-slate-200 text-left">Question</th>
                {OPTIONS.map(opt => (
                  <th key={opt} className="p-3 border-b border-slate-200 font-semibold text-blue-800">Choice {opt}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {Array.from({ length: QUESTION_COUNT }).map((_, idx) => {
                const qNum = idx + 1;
                return (
                  <tr key={qNum} className="hover:bg-slate-50">
                    <td className="p-2 border-b border-slate-100 font-medium text-slate-600 text-left pl-4">Q{qNum}</td>
                    {OPTIONS.map(opt => (
                      <td key={opt} className="p-2 border-b border-slate-100">
                        <input
                          type="number"
                          min="0"
                          max="10"
                          value={scoringKey[qNum]?.[opt] ?? 0}
                          onChange={(e) => handleScoreChange(qNum, opt, e.target.value)}
                          className="w-16 text-center border border-slate-200 rounded p-1 focus:ring-1 focus:ring-blue-500 focus:outline-none"
                        />
                      </td>
                    ))}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="flex justify-end pt-4">
        <button
          onClick={onNext}
          className="flex items-center gap-2 bg-blue-600 text-white px-6 py-3 rounded-lg font-semibold hover:bg-blue-700 transition-all shadow-md hover:shadow-lg"
        >
          Start Grading <ArrowRight className="w-5 h-5" />
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ScoringKey, StudentResult, OPTIONS, QUESTION_COUNT, Option } from '../types';
import { PlusCircle, Trash2, Printer, UserPlus, CheckCircle2 } from 'lucide-react';

interface StudentGradingProps {
  scoringKey: ScoringKey;
  students: StudentResult[];
  onAddStudent: (student: StudentResult) => void;
  onDeleteStudent: (id: string) => void;
  onPrintStudent: (student: StudentResult) => void;
}

export const StudentGrading: React.FC<StudentGradingProps> = ({
  scoringKey,
  students,
  onAddStudent,
  onDeleteStudent,
  onPrintStudent,
}) => {
  const [currentName, setCurrentName] = useState('');
  const [currentAnswers, setCurrentAnswers] = useState<Record<number, Option>>({});

  const calculateScore = (answers: Record<number, Option>) => {
    let total = 0;
    const qScores: Record<number, number> = {};

    for (let i = 1; i <= QUESTION_COUNT; i++) {
      const selectedOption = answers[i];
      const points = selectedOption ? scoringKey[i][selectedOption] : 0;
      qScores[i] = points;
      total += points;
    }
    return { total, qScores };
  };

  const handleOptionSelect = (qIndex: number, option: Option) => {
    setCurrentAnswers(prev => ({ ...prev, [qIndex]: option }));
  };

  const handleSaveStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentName.trim()) return;

    // Ensure all questions are answered or default to 0 points (handled in calc)
    // We allow submission even if some are missed, treated as 0.

    const { total, qScores } = calculateScore(currentAnswers);

    const newStudent: StudentResult = {
      id: Date.now().toString(),
      name: currentName,
      answers: currentAnswers,
      totalScore: total,
      questionScores: qScores,
    };

    onAddStudent(newStudent);
    setCurrentName('');
    setCurrentAnswers({});
  };

  const currentScorePreview = calculateScore(currentAnswers).total;

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in fade-in duration-500">

      {/* Entry Form */}
      <div className="lg:col-span-1 space-y-6">
        <div className="bg-white p-6 rounded-xl shadow-lg border-t-4 border-blue-600 sticky top-6">
          <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
            <UserPlus className="w-5 h-5 text-blue-600" />
            New Student Entry
          </h2>

          <form onSubmit={handleSaveStudent}>
            <div className="mb-6">
              <label className="block text-sm font-medium text-slate-600 mb-1">Student Name</label>
              <input
                autoFocus
                value={currentName}
                onChange={(e) => setCurrentName(e.target.value)}
                className="w-full border border-slate-300 rounded-lg p-2.5 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                placeholder="Enter full name"
                required
              />
            </div>

            <div className="space-y-4 mb-6 max-h-[50vh] overflow-y-auto pr-2 custom-scrollbar">
              {Array.from({ length: QUESTION_COUNT }).map((_, idx) => {
                const qNum = idx + 1;
                return (
                  <div key={qNum} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg border border-slate-100">
                    <span className="font-semibold text-slate-700 w-8">Q{qNum}</span>
                    <div className="flex gap-1">
                      {OPTIONS.map(opt => {
                        const isSelected = currentAnswers[qNum] === opt;
                        const weight = scoringKey[qNum][opt];
                        return (
                          <button
                            key={opt}
                            type="button"
                            onClick={() => handleOptionSelect(qNum, opt)}
                            className={`w-9 h-9 rounded-full text-sm font-medium transition-all ${
                              isSelected
                                ? 'bg-blue-600 text-white shadow-md scale-105'
                                : 'bg-white text-slate-600 border border-slate-200 hover:border-blue-300'
                            }`}
                            title={`Worth ${weight} marks`}
                          >
                            {opt}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>

            <div className="flex items-center justify-between pt-4 border-t border-slate-100">
              <div className="text-sm text-slate-500">
                Score Preview: <span className="font-bold text-blue-600 text-lg">{currentScorePreview}</span>
              </div>
              <button
                type="submit"
                disabled={!currentName.trim()}
                className="bg-blue-600 disabled:opacity-50 text-white px-6 py-2 rounded-lg font-semibold hover:bg-blue-700 transition-colors flex items-center gap-2"
              >
                <PlusCircle className="w-4 h-4" />
                Save Result
              </button>
            </div>
          </form>
        </div>
      </div>

      {/* Results List */}
      <div className="lg:col-span-2">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h2 className="text-xl font-bold text-slate-800 mb-4 flex items-center gap-2">
            <CheckCircle2 className="w-5 h-5 text-green-600" />
            Graded Students ({students.length})
          </h2>

          {students.length === 0 ? (
            <div className="text-center py-12 text-slate-400 bg-slate-50 rounded-lg border-dashed border-2 border-slate-200">
              <p>No students graded yet.</p>
              <p className="text-sm">Use the form to add student results.</p>
            </div>
          ) : (
            <div className="overflow-hidden rounded-lg border border-slate-200">
              <table className="w-full text-sm text-left">
                <thead className="bg-slate-50 text-slate-700 font-semibold uppercase text-xs">
                  <tr>
                    <th className="p-4">Name</th>
                    <th className="p-4 text-center">Score</th>
                    <th className="p-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {students.map((student) => (
                    <tr key={student.id} className="hover:bg-slate-50 group">
                      <td className="p-4 font-medium text-slate-800">{student.name}</td>
                      <td className="p-4 text-center">
                        <span className="inline-flex items-center justify-center px-3 py-1 rounded-full bg-blue-100 text-blue-800 font-bold">
                          {student.totalScore}
                        </span>
                      </td>
                      <td className="p-4 text-right">
                        <div className="flex items-center justify-end gap-2">
                          <button
                            onClick={() => onPrintStudent(student)}
                            className="p-2 text-slate-500 hover:text-blue-600 hover:bg-blue-50 rounded transition-colors"
                            title="Print Report"
                          >
                            <Printer className="w-4 h-4" />
                          </button>
                          <button
                            onClick={() => onDeleteStudent(student.id)}
                            className="p-2 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                            title="Delete"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { TestMetadata, StudentResult, OPTIONS, QUESTION_COUNT } from '../types';

interface PrintReportProps {
  metadata: TestMetadata;
  student: StudentResult | null;
}

export const PrintReport: React.FC<PrintReportProps> = ({ metadata, student }) => {
  if (!student) return null;

  return (
    <div className="print-only fixed inset-0 bg-white z-[9999] p-8 text-black">
      {/* Header */}
      <div className="border-b-2 border-black pb-4 mb-6">
        <h1 className="text-3xl font-bold text-center uppercase tracking-wide mb-2">{metadata.schoolName}</h1>
        <div className="flex justify-between text-sm mt-4">
          <div className="space-y-1">
            <p><span className="font-bold">Test:</span> {metadata.testName}</p>
            <p><span className="font-bold">Teacher:</span> {metadata.teacherName}</p>
          </div>
          <div className="space-y-1 text-right">
            <p><span className="font-bold">Grade:</span> {metadata.grade}</p>
            <p><span className="font-bold">Section:</span> {metadata.section}</p>
          </div>
        </div>
      </div>

      {/* Student Info */}
      <div className="bg-gray-100 p-4 rounded mb-6 flex justify-between items-center border border-gray-300">
        <div>
          <span className="text-gray-600 text-sm uppercase font-bold tracking-wider">Student Name</span>
          <p className="text-xl font-bold">{student.name}</p>
        </div>
        <div className="text-right">
          <span className="text-gray-600 text-sm uppercase font-bold tracking-wider">Total Score</span>
          <p className="text-3xl font-bold">{student.totalScore}</p>
        </div>
      </div>

      {/* Detailed Breakdown */}
      <div className="mb-8">
        <h3 className="font-bold border-b border-gray-300 mb-2 pb-1">Performance Breakdown</h3>
        <table className="w-full text-sm border-collapse border border-gray-300">
          <thead>
            <tr className="bg-gray-200">
              <th className="border border-gray-300 p-2 text-center w-16">Q #</th>
              <th className="border border-gray-300 p-2 text-center">Selected Choice</th>
              <th className="border border-gray-300 p-2 text-center w-24">Marks</th>
            </tr>
          </thead>
          <tbody>
            {Array.from({ length: QUESTION_COUNT }).map((_, idx) => {
              const qNum = idx + 1;
              const choice = student.answers[qNum];
              const score = student.questionScores[qNum];

              return (
                <tr key={qNum}>
                  <td className="border border-gray-300 p-2 text-center font-medium">{qNum}</td>
                  <td className="border border-gray-300 p-2 text-center">
                    <div className="inline-flex gap-2">
                       {OPTIONS.map(opt => (
                         <span key={opt} className={`w-6 h-6 flex items-center justify-center rounded-full text-xs ${choice === opt ? 'bg-black text-white font-bold' : 'text-gray-300 border border-gray-200'}`}>
                           {opt}
                         </span>
                       ))}
                    </div>
                  </td>
                  <td className="border border-gray-300 p-2 text-center font-bold">{score}</td>
                </tr>
              );
            })}
          </tbody>
          <tfoot>
             <tr className="bg-gray-100">
                <td colSpan={2} className="border border-gray-300 p-2 text-right font-bold uppercase">Total Marks</td>
                <td className="border border-gray-300 p-2 text-center font-bold text-lg">{student.totalScore}</td>
             </tr>
          </tfoot>
        </table>
      </div>

      {/* Footer */}
      <div className="mt-12 text-center text-xs text-gray-500 pt-4 border-t border-gray-300">
        <p>Report generated by ScienceGrade Pro</p>
        <p>{new Date().toLocaleDateString()} {new Date().toLocaleTimeString()}</p>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { TestSetup } from './components/TestSetup';
import { StudentGrading } from './components/StudentGrading';
import { PrintReport } from './components/PrintReport';
import { TestMetadata, ScoringKey, StudentResult } from './types';
import { Beaker, ChevronRight } from 'lucide-react';

const App: React.FC = () => {
  // State
  const [step, setStep] = useState<1 | 2>(1);
  const [metadata, setMetadata] = useState<TestMetadata>({
    testName: '',
    teacherName: '',
    schoolName: '',
    grade: '',
    section: '',
  });
  const [scoringKey, setScoringKey] = useState<ScoringKey>({});
  const [students, setStudents] = useState<StudentResult[]>([]);

  // Print State
  const [studentToPrint, setStudentToPrint] = useState<StudentResult | null>(null);

  // Load from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('scienceGradePro_v1');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setMetadata(parsed.metadata);
        setScoringKey(parsed.scoringKey);
        setStudents(parsed.students);
        // Don't auto-set step, let user start at 1 to verify info, 
        // but if data exists, they can click next easily.
      } catch (e) {
        console.error("Failed to load saved data");
      }
    }
  }, []);

  // Save to local storage on change
  useEffect(() => {
    const data = { metadata, scoringKey, students };
    localStorage.setItem('scienceGradePro_v1', JSON.stringify(data));
  }, [metadata, scoringKey, students]);

  const handleAddStudent = (student: StudentResult) => {
    setStudents([student, ...students]);
  };

  const handleDeleteStudent = (id: string) => {
    setStudents(students.filter(s => s.id !== id));
  };

  const handlePrintStudent = (student: StudentResult) => {
    setStudentToPrint(student);
    // Use timeout to allow React to render the print component before triggering print dialog
    setTimeout(() => {
        window.print();
        // Clear print state after printing dialog closes (or user cancels)
        // Note: window.print is blocking in many browsers, but not all. 
        // We leave the state briefly. In a real app, we might use onafterprint event.
        const cleanup = () => { setStudentToPrint(null); };
        window.addEventListener('afterprint', cleanup, { once: true });

        // Fallback cleanup for browsers that don't block
        setTimeout(cleanup, 1000);
    }, 100);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans selection:bg-blue-200">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-40 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-blue-600 p-2 rounded-lg">
              <Beaker className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-lg font-bold text-slate-800 leading-tight">ScienceGrade Pro</h1>
              <p className="text-xs text-slate-500">MCQ Correction Tool</p>
            </div>
          </div>

          <div className="flex items-center gap-4 text-sm font-medium">
             <div className={`px-3 py-1 rounded-full ${step === 1 ? 'bg-blue-100 text-blue-700' : 'text-slate-500'}`}>
                1. Setup
             </div>
             <ChevronRight className="w-4 h-4 text-slate-300" />
             <div className={`px-3 py-1 rounded-full ${step === 2 ? 'bg-blue-100 text-blue-700' : 'text-slate-500'}`}>
                2. Grading
             </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 no-print">
        {step === 1 ? (
          <TestSetup 
            metadata={metadata}
            scoringKey={scoringKey}
            onMetadataChange={setMetadata}
            onScoringKeyChange={setScoringKey}
            onNext={() => setStep(2)}
          />
        ) : (
          <div>
            <div className="mb-6 flex items-center justify-between">
              <button 
                onClick={() => setStep(1)}
                className="text-slate-500 hover:text-slate-800 text-sm font-medium hover:underline"
              >
                ← Back to Setup
              </button>
              <div className="text-right">
                <h2 className="font-bold text-slate-800">{metadata.testName || 'Untitled Test'}</h2>
                <p className="text-sm text-slate-500">{students.length} students graded</p>
              </div>
            </div>

            <StudentGrading 
              scoringKey={scoringKey}
              students={students}
              onAddStudent={handleAddStudent}
              onDeleteStudent={handleDeleteStudent}
              onPrintStudent={handlePrintStudent}
            />
          </div>
        )}
      </main>

      {/* Hidden Print Component - Only visible during print */}
      <PrintReport metadata={metadata} student={studentToPrint} />
    </div>
  );
};

const rootElement = document.getElementById('root');
if (!rootElement) throw new Error("Could not find root element to mount to");

const root = createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

