import React, { useEffect, useRef, useState } from 'react';
import { TestMetadata, StudentResult, OPTIONS, QUESTION_COUNT } from '../types';
import { Printer, Download, X, Loader2 } from 'lucide-react';

interface PrintReportProps {
  metadata: TestMetadata;
  student: StudentResult | null;
  initialAction: 'print' | 'download' | null;
  onClose: () => void;
}

export const PrintReport: React.FC<PrintReportProps> = ({ metadata, student, initialAction, onClose }) => {
  const reportRef = useRef<HTMLDivElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // Auto-trigger action on mount if provided
  useEffect(() => {
    if (initialAction === 'print') {
      handlePrint();
    } else if (initialAction === 'download') {
      handleDownloadPdf();
    }
  }, [initialAction]);

  if (!student) return null;

  const handlePrint = () => {
    // Wait for a brief moment to ensure rendering is complete
    setTimeout(() => {
      window.print();
    }, 500);
  };

  const handleDownloadPdf = () => {
    if (!reportRef.current || !(window as any).html2pdf) return;

    setIsProcessing(true);
    const element = reportRef.current;

    // We clone the element to modify it for PDF if necessary, or just use it directly.
    // html2pdf works best with the visible element.
    const opt = {
      margin: [0.3, 0.3], // inches
      filename: `${student.name.replace(/[^a-z0-9]/gi, '_')}_Report.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, scrollY: 0 },
      jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
    };

    (window as any).html2pdf().set(opt).from(element).save()
      .then(() => setIsProcessing(false))
      .catch((err: any) => {
        console.error("PDF Error:", err);
        setIsProcessing(false);
      });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-slate-900/70 p-4 print:p-0 print:bg-white print:static print:block">

      {/* Container that centers the paper */}
      <div className="relative w-full max-w-[210mm] print:max-w-none print:w-full">

        {/* Toolbar - Hidden in Print */}
        <div className="mb-4 flex items-center justify-between bg-white p-4 rounded-lg shadow-md print:hidden animate-in fade-in slide-in-from-top-4">
          <h3 className="font-bold text-slate-800">Report Preview</h3>
          <div className="flex items-center gap-2">
            <button
              onClick={handleDownloadPdf}
              disabled={isProcessing}
              className="flex items-center gap-2 px-4 py-2 bg-purple-600 text-white rounded hover:bg-purple-700 transition-colors disabled:opacity-50"
            >
              {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Download className="w-4 h-4" />}
              Save PDF
            </button>
            <button
              onClick={handlePrint}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
            >
              <Printer className="w-4 h-4" />
              Print
            </button>
            <button
              onClick={onClose}
              className="flex items-center gap-2 px-4 py-2 bg-slate-200 text-slate-700 rounded hover:bg-slate-300 transition-colors"
            >
              <X className="w-4 h-4" />
              Close
            </button>
          </div>
        </div>

        {/* The Paper - Always Visible */}
        <div 
          ref={reportRef}
          className="bg-white text-black shadow-2xl print:shadow-none min-h-[297mm] p-[20mm] print:p-0 print:m-0 mx-auto"
        >
          {/* Report Content */}
          <div className="border-b-2 border-black pb-4 mb-6">
            <h1 className="text-3xl font-bold text-center uppercase tracking-wide mb-2">{metadata.schoolName}</h1>
            <div className="flex justify-between text-sm mt-6">
              <div className="space-y-1">
                <p><span className="font-bold">Test:</span> {metadata.testName}</p>
                <p><span className="font-bold">Teacher:</span> {metadata.teacherName}</p>
              </div>
              <div className="space-y-1 text-right">
                <p><span className="font-bold">Grade:</span> {metadata.grade}</p>
                <p><span className="font-bold">Section:</span> {metadata.section}</p>
              </div>
            </div>
          </div>

          <div className="bg-slate-50 border border-slate-300 p-4 rounded mb-8 flex justify-between items-center print:bg-gray-100 print:border-gray-300">
            <div>
              <span className="text-slate-500 text-xs uppercase font-bold tracking-wider print:text-black">Student Name</span>
              <p className="text-2xl font-bold">{student.name}</p>
            </div>
            <div className="text-right">
              <span className="text-slate-500 text-xs uppercase font-bold tracking-wider print:text-black">Total Score</span>
              <p className="text-4xl font-bold text-blue-700 print:text-black">{student.totalScore}</p>
            </div>
          </div>

          <div className="mb-8">
            <h3 className="font-bold border-b border-gray-300 mb-2 pb-1 text-lg">Performance Breakdown</h3>
            <table className="w-full text-sm border-collapse border border-gray-300 mt-4">
              <thead>
                <tr className="bg-gray-100 print:bg-gray-200">
                  <th className="border border-gray-300 p-3 text-center w-16 bg-gray-100 print:bg-gray-200">Q #</th>
                  <th className="border border-gray-300 p-3 text-center">Selected Choice</th>
                  <th className="border border-gray-300 p-3 text-center w-24 bg-gray-100 print:bg-gray-200">Marks</th>
                </tr>
              </thead>
              <tbody>
                {Array.from({ length: QUESTION_COUNT }).map((_, idx) => {
                  const qNum = idx + 1;
                  const choice = student.answers[qNum];
                  const score = student.questionScores[qNum];

                  return (
                    <tr key={qNum}>
                      <td className="border border-gray-300 p-2 text-center font-bold bg-slate-50 print:bg-white">{qNum}</td>
                      <td className="border border-gray-300 p-2 text-center">
                        <div className="flex items-center justify-center gap-3">
                           {OPTIONS.map(opt => (
                             <span 
                               key={opt} 
                               className={`w-7 h-7 flex items-center justify-center rounded-full text-xs font-bold border 
                                 ${choice === opt 
                                   ? 'bg-black text-white border-black print:bg-black print:text-white' 
                                   : 'text-gray-400 border-gray-200 print:text-gray-400'
                                 }`}
                             >
                               {opt}
                             </span>
                           ))}
                        </div>
                      </td>
                      <td className="border border-gray-300 p-2 text-center font-bold text-base">{score}</td>
                    </tr>
                  );
                })}
              </tbody>
              <tfoot>
                 <tr className="bg-gray-100 print:bg-gray-200">
                    <td colSpan={2} className="border border-gray-300 p-3 text-right font-bold uppercase">Total Marks</td>
                    <td className="border border-gray-300 p-3 text-center font-bold text-xl">{student.totalScore}</td>
                 </tr>
              </tfoot>
            </table>
          </div>

          <div className="mt-12 text-center text-xs text-gray-500 pt-6 border-t border-gray-200 print:text-black">
            <p>Report generated by ScienceGrade Pro</p>
            <p>{new Date().toLocaleDateString()} {new Date().toLocaleTimeString()}</p>
          </div>
        </div>
      </div>
    </div>
  );
};

